import socket
from multiprocessing import Queue


class Listener:
    """UDP listener that listens on specified IP and port and puts received data into queue.

    :param ip: IP address to listen on.
    :type ip: str
    :param port: Port to listen on.
    :type port: int
    :param queue: Queue to put received data into.
    :type queue: Queue
    """

    def __init__(self, ip: str, port: int, queue: Queue) -> None:
        self.ip = ip
        self.port = port
        self.queue = queue

    def run(self):
        with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as s:
            s.bind((self.ip, self.port))
            while True:
                data = s.recvfrom(8192)
                self.queue.put(data)
                if not data:
                    break
